Decode only a quoted name (already verified in scratch: all 79 fontforge tests pass, cargo fmt check and clippy --all-targets clean):
    // FontForge quotes a glyph name only when it is not all ASCII, and a quoted
    // name is in its modified UTF-7, like subtable, lookup, class and nameid
    // strings. An unquoted name is literal, `+` included. FontForge can leave
    // whitespace after the closing quote.
    let name_line = name_line.trim();
    let decoded_name = match name_line
        .strip_prefix('"')
        .and_then(|n| n.strip_suffix('"'))
    {
        Some(quoted) => decode_utf7(quoted),
        None => name_line.to_string(),
    };
    let glyph_name = decoded_name.as_str();
